pub fn lis(xs: List[Int]) -> List[Int] {
  let n = xs.len()
  var f: List[Int] = []
  for _i in range(0, n) {
    f = f.push(0)
  }
  for k in range(0, n) {
    let i = n - 1 - k
    let xi = xs.get_or(i, 0)
    var best = 1
    for j in range(i + 1, n) {
      if xs.get_or(j, 0) > xi and f.get_or(j, 0) + 1 > best {
        best = f.get_or(j, 0) + 1
      }
    }
    f = f.set(i, best)
  }
  var maxl = 0
  for v in f {
    if v > maxl {
      maxl = v
    }
  }
  var result: List[Int] = []
  var prev = -1
  var need = maxl
  while need > 0 {
    var bi = -1
    var bv = 0
    for j in range(prev + 1, n) {
      let xj = xs.get_or(j, 0)
      let fits = prev < 0 or xj > xs.get_or(prev, 0)
      if fits and f.get_or(j, 0) == need {
        if bi < 0 or xj < bv {
          bi = j
          bv = xj
        }
      }
    }
    result = result.push(bv)
    prev = bi
    need = need - 1
  }
  return result
}
